{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h2",
        "intro_text",
        "techniques_h3",
        "time_blocking_card",
        "prioritization_card",
        "pomodoro_card",
        "quick_actions_h3",
        "quick_actions_stack"
      ]
    },
    "title_h2": {
      "type": "Text",
      "props": {
        "text": "Effective Time Management Strategies for Busy Students",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Balancing full-time studies and a part-time job requires a structured approach to time management. With 20 hours of classes, 15 hours of work, and 25 hours allocated for study, a total of 60 hours per week are committed, leaving ample time for personal needs when managed efficiently. These techniques will help you maximize productivity and minimize stress.",
        "variant": "body"
      },
      "children": []
    },
    "techniques_h3": {
      "type": "Text",
      "props": {
        "text": "Recommended Time Management Techniques",
        "variant": "h3"
      },
      "children": []
    },
    "time_blocking_card": {
      "type": "Card",
      "props": {},
      "children": [
        "time_blocking_header_stack",
        "time_blocking_intro_text",
        "time_blocking_how_helps_label",
        "time_blocking_how_helps_text",
        "time_blocking_key_steps_label",
        "time_blocking_key_steps_list"
      ]
    },
    "time_blocking_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "time_blocking_icon",
        "time_blocking_title_h3"
      ]
    },
    "time_blocking_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000472_01_2_calendar.svg"
      },
      "children": []
    },
    "time_blocking_title_h3": {
      "type": "Text",
      "props": {
        "text": "Time Blocking",
        "variant": "h3"
      },
      "children": []
    },
    "time_blocking_intro_text": {
      "type": "Text",
      "props": {
        "text": "Time blocking involves scheduling every hour of your day in advance, dedicating specific blocks of time to tasks like classes, work, study, and even breaks or personal activities.",
        "variant": "body"
      },
      "children": []
    },
    "time_blocking_how_helps_label": {
      "type": "Text",
      "props": {
        "text": "How it helps:",
        "variant": "label"
      },
      "children": []
    },
    "time_blocking_how_helps_text": {
      "type": "Text",
      "props": {
        "text": "Creates a visual map of your week, ensuring all commitments are accounted for and preventing overcommitment. It helps you carve out dedicated, uninterrupted blocks for deep study.",
        "variant": "body"
      },
      "children": []
    },
    "time_blocking_key_steps_label": {
      "type": "Text",
      "props": {
        "text": "Key Steps:",
        "variant": "label"
      },
      "children": []
    },
    "time_blocking_key_steps_list": {
      "type": "List",
      "props": {},
      "children": [
        "time_blocking_step1",
        "time_blocking_step2",
        "time_blocking_step3",
        "time_blocking_step4"
      ]
    },
    "time_blocking_step1": {
      "type": "Text",
      "props": {
        "text": "Map Fixed Commitments: Start by blocking out your 20 hours of classes and 15 hours of work.",
        "variant": "body"
      },
      "children": []
    },
    "time_blocking_step2": {
      "type": "Text",
      "props": {
        "text": "Schedule Study Blocks: Integrate 25 hours of study time into your week, breaking it into manageable 2-3 hour sessions.",
        "variant": "body"
      },
      "children": []
    },
    "time_blocking_step3": {
      "type": "Text",
      "props": {
        "text": "Include Personal Time: Don't forget to schedule time for meals, exercise, social activities, and adequate sleep to avoid burnout.",
        "variant": "body"
      },
      "children": []
    },
    "time_blocking_step4": {
      "type": "Text",
      "props": {
        "text": "Review Weekly: Adjust your blocks weekly based on assignment deadlines and work schedule changes.",
        "variant": "body"
      },
      "children": []
    },
    "prioritization_card": {
      "type": "Card",
      "props": {},
      "children": [
        "prioritization_header_stack",
        "prioritization_intro_text",
        "prioritization_how_helps_label",
        "prioritization_how_helps_text",
        "prioritization_key_steps_label",
        "prioritization_key_steps_list"
      ]
    },
    "prioritization_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "prioritization_icon",
        "prioritization_title_h3"
      ]
    },
    "prioritization_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000477_01_2_list-check.svg"
      },
      "children": []
    },
    "prioritization_title_h3": {
      "type": "Text",
      "props": {
        "text": "Prioritization Matrix (Eisenhower Method)",
        "variant": "h3"
      },
      "children": []
    },
    "prioritization_intro_text": {
      "type": "Text",
      "props": {
        "text": "This method helps you categorize tasks by urgency and importance, allowing you to focus on what truly matters and avoid getting bogged down by less critical activities.",
        "variant": "body"
      },
      "children": []
    },
    "prioritization_how_helps_label": {
      "type": "Text",
      "props": {
        "text": "How it helps:",
        "variant": "label"
      },
      "children": []
    },
    "prioritization_how_helps_text": {
      "type": "Text",
      "props": {
        "text": "Essential for managing study tasks and work assignments, ensuring that high-impact tasks are completed first, especially when time is limited.",
        "variant": "body"
      },
      "children": []
    },
    "prioritization_key_steps_label": {
      "type": "Text",
      "props": {
        "text": "Key Steps:",
        "variant": "label"
      },
      "children": []
    },
    "prioritization_key_steps_list": {
      "type": "List",
      "props": {},
      "children": [
        "prioritization_step1",
        "prioritization_step2",
        "prioritization_step3",
        "prioritization_step4",
        "prioritization_step5"
      ]
    },
    "prioritization_step1": {
      "type": "Text",
      "props": {
        "text": "Urgent & Important (Do First): Assignments due soon, critical work tasks.",
        "variant": "body"
      },
      "children": []
    },
    "prioritization_step2": {
      "type": "Text",
      "props": {
        "text": "Important, Not Urgent (Schedule): Long-term projects, exam preparation, skill development.",
        "variant": "body"
      },
      "children": []
    },
    "prioritization_step3": {
      "type": "Text",
      "props": {
        "text": "Urgent, Not Important (Delegate/Minimize): Non-critical emails, certain social requests (if possible).",
        "variant": "body"
      },
      "children": []
    },
    "prioritization_step4": {
      "type": "Text",
      "props": {
        "text": "Neither Urgent Nor Important (Eliminate): Distractions, time-wasting activities.",
        "variant": "body"
      },
      "children": []
    },
    "prioritization_step5": {
      "type": "Text",
      "props": {
        "text": "Daily Review: At the start of each day, quickly categorize your tasks to guide your focus.",
        "variant": "body"
      },
      "children": []
    },
    "pomodoro_card": {
      "type": "Card",
      "props": {},
      "children": [
        "pomodoro_header_stack",
        "pomodoro_intro_text",
        "pomodoro_how_helps_label",
        "pomodoro_how_helps_text",
        "pomodoro_key_steps_label",
        "pomodoro_key_steps_list"
      ]
    },
    "pomodoro_header_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "pomodoro_icon",
        "pomodoro_title_h3"
      ]
    },
    "pomodoro_icon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000474_01_2_clock.svg"
      },
      "children": []
    },
    "pomodoro_title_h3": {
      "type": "Text",
      "props": {
        "text": "Pomodoro Technique",
        "variant": "h3"
      },
      "children": []
    },
    "pomodoro_intro_text": {
      "type": "Text",
      "props": {
        "text": "The Pomodoro Technique uses a timer to break down work into focused intervals, traditionally 25 minutes in length, separated by short breaks.",
        "variant": "body"
      },
      "children": []
    },
    "pomodoro_how_helps_label": {
      "type": "Text",
      "props": {
        "text": "How it helps:",
        "variant": "label"
      },
      "children": []
    },
    "pomodoro_how_helps_text": {
      "type": "Text",
      "props": {
        "text": "Improves focus and prevents mental fatigue during study sessions and work tasks. It ensures you make consistent progress without feeling overwhelmed.",
        "variant": "body"
      },
      "children": []
    },
    "pomodoro_key_steps_label": {
      "type": "Text",
      "props": {
        "text": "Key Steps:",
        "variant": "label"
      },
      "children": []
    },
    "pomodoro_key_steps_list": {
      "type": "List",
      "props": {},
      "children": [
        "pomodoro_step1",
        "pomodoro_step2",
        "pomodoro_step3",
        "pomodoro_step4"
      ]
    },
    "pomodoro_step1": {
      "type": "Text",
      "props": {
        "text": "Set a Timer: Work on a single task for 25 minutes.",
        "variant": "body"
      },
      "children": []
    },
    "pomodoro_step2": {
      "type": "Text",
      "props": {
        "text": "Take a Short Break: After 25 minutes, take a 5-minute break (stretch, walk, hydrate).",
        "variant": "body"
      },
      "children": []
    },
    "pomodoro_step3": {
      "type": "Text",
      "props": {
        "text": "Repeat: After four \"Pomodoros\" (100 minutes of work, 15 minutes of short breaks), take a longer break (15-30 minutes).",
        "variant": "body"
      },
      "children": []
    },
    "pomodoro_step4": {
      "type": "Text",
      "props": {
        "text": "Track Progress: Note completed Pomodoros to see your productivity.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "button_google_calendar",
        "button_todoist",
        "button_pomodoro_info"
      ]
    },
    "button_google_calendar": {
      "type": "Button",
      "props": {
        "label": "Explore Time Blocking Tools: Google Calendar"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://calendar.google.com"
          }
        }
      },
      "children": []
    },
    "button_todoist": {
      "type": "Button",
      "props": {
        "label": "Try a Prioritization Tool: Todoist"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://todoist.com"
          }
        }
      },
      "children": []
    },
    "button_pomodoro_info": {
      "type": "Button",
      "props": {
        "label": "Learn More About Pomodoro Technique"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://francescocirillo.com/pages/pomodoro-technique"
          }
        }
      },
      "children": []
    }
  }
}
